import math

def paths(n, m):
	if min(n, m) < 0:
		return 0
	return math.factorial(n + m) / math.factorial(n) / math.factorial(m)
T = int(input())
for cs in range(T):
	res = []
	(N, M, K) = [int(x) for x in input().split()]
	(x, y) = (0, 0)
	while (x, y) != (N, M):
		n = paths(N - x - 1, M - y)
		if x + 1 <= N and K < n:
			res.append('H')
			x += 1
		else:
			K -= n
			res.append('V')
			y += 1
	print(''.join(res))
